const UNIT_NAMES=["哈克","哈克","ハク","ハク","オシュトル","オシュトル","オシュトル","オシュトル","オシュトル","オシュトル","オシュトル","オシュトル","奧修特爾","奧修特爾","右近","オシュトル","オシュトル","オシュトル","オシュトル","オシュトル","久遠","クオン","クオン","クオン","クオン","麻呂呂","マロロ","露露緹耶","露露緹耶","ルルティエ","烏露露","薩拉娜","烏露露‧薩拉娜","鵟","鵟","扇","貓音","奇羽琉","阿圖依","阿圖依","杏樹","アンジュ","安珠","亞庫托瓦爾特","亞庫托瓦爾特","魁梧的男人","詩諾農","宗近","ムネチカ","ムネチカ","芙米露露","藤香","卡露拉","卡繆","阿露露","アルルゥ","克羅","貝納威","ウルトリィ","伯勞","伯勞","水戶","帝皇","穗香","御雷","ミカヅチ","左近","ミカヅチ","凸砰砰","波科伊南特","沃西斯","ウォシス","謝斯利卡","シャスリカ","シャスリカ","利維艾爾尼","リヴェルニ","リヴェルニ","拉比艾","ラヴィエ","ラヴィエ","美琉樹","ミルージュ","武賴","武賴","ヴライ","ヴライ","雷光","ライコウ","七理夜","シチーリヤ","シチーリヤ","袞杜魯亞","恩圖亞","エントゥア","索楊克庫爾","時櫻","オーゼン","シス","ヤシュマ","イラワジ","ゲンホウ","伊塔克","尤里","恩哈萊","チャラフン","トリコリ","女将","","","","澤古尼","環","環","莎莎菈","莎莎菈","大和劍兵","エンナカムイ剣兵","クジュウリ剣兵","イズルハ剣兵","ナコク剣兵","劍奴","大和劍兵長","エンナカムイ剣兵長","クジュウリ剣兵長","イズルハ剣兵長","ナコク剣兵長","大和弓兵","エンナカムイ弓兵","クジュウリ弓兵","イズルハ弓兵","ナコク弓兵","大和咒兵","エンナカムイ呪兵","クジュウリ呪兵","イズルハ呪兵","ナコク呪兵","大和騎兵","エンナカムイ騎兵","クジュウリ騎兵","イズルハ騎兵","ナコク騎兵","大和騎兵長","傭兵","伯勞一派","反對派","ウコン一派","鵟一派","傭兵","伯勞一派","反對派","ウコン一派","鵟一派","蒙面兵","古圖艾達爾","屍骸","覆面兵顔バレ","屍骸演出用","烏茲魯沙劍兵","烏茲魯沙隊長","烏茲魯沙弓兵","烏茲魯沙咒兵","圖斯庫爾劍兵","圖斯庫爾弓兵","圖斯庫爾術兵","圖斯庫爾騎兵","ヤマト逓信兵","大和槍兵","エンナカムイ槍兵","クジュウリ槍兵","イズルハ槍兵","ナコク槍兵","大和槍兵長","エンナカムイ槍兵長","クジュウリ槍兵長","イズルハ槍兵長","ナコク槍兵長","分隊ヤマト兵待機","分隊ヤマト兵走り","分隊ヤマト兵死体","分隊蛮族兵待機","分隊蛮族兵走り","分隊蛮族兵死体","分隊剣奴待機","分隊剣奴走り","分隊剣奴死体","分隊ヤマト兵待機","分隊蛮族兵待機","分隊剣奴待機","小隊ヤマト兵待機","小隊蛮族兵待機","小隊剣奴待機","ホロロン鳥","可可啵","克拉琳","クラリン","ムックル","ウォプタル","ウォプタル","ウォプタル","奇奇利","巨奇利","祟","祟溫凱米","冰凍祟溫凱米","獒切","亞拉獒切","ガウンジ","ガウンジ","男性","ヤマト市民","白衣の男性","荷車","荷車","荷車","気球","柵欄","柵","楯","石頭","石","石","石","塩になった覆面兵","塩の山","矢","矢","矢","矢","刺さっている矢","刺さっている矢","刺さっている矢","刺さっている矢","腐肉","冷卻管道","旗","旗","旗","旗","旗","旗","旗","旗","旗","旗","旗","軍旗","旗-騎乗用","旗-騎乗用","旗-騎乗用","旗-騎乗用","旗-騎乗用","旗-騎乗用","旗-騎乗用","旗-騎乗用","旗-騎乗用","旗-騎乗用","旗-騎乗用","旗-騎乗用","物資","物資","物資","物資","檻","隠し大岩","崖の巨石","崖の先端","雪の崖先","尖った岩A","尖った岩B","尖った岩C","クレーターA","クレーターB","クレーターC","破壊岩A","破壊岩B","破壊岩C","岩場の岩A","岩場の岩B","岩場の岩C","岩場の草A","ウズールッシャテント","ヤマトテント","クオンテント","建物","建物","建物","カプセル","広がる曼荼羅","八本の尖柱","八角柱","幕","照明","焚き火","ムネチカバリア","延焼","網","祈力朋壹號","祈力朋貳號","魔絲魔絲","シュマリ","シュマリ","ヒララ","レウレウ","伯勞的斧頭","德古恰卡","？"];
const HTML="<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>传颂之物 虚伪的假面 · 人物修改器</title>\n<style>\n:root{\n  --bg:#0f1218;--panel:#181d27;--panel2:#1f2634;--line:#2b3547;\n  --txt:#e7ecf5;--sub:#93a0b4;--acc:#d4a94e;--acc2:#5b8cff;--ok:#43c97d;--warn:#e0635c;\n}\n*{box-sizing:border-box}\nbody{margin:0;font-family:\"Segoe UI\",\"Microsoft YaHei\",sans-serif;background:var(--bg);color:var(--txt);height:100vh;display:flex;flex-direction:column}\nheader{padding:14px 20px;background:linear-gradient(180deg,#1a2130,#141924);border-bottom:1px solid var(--line);display:flex;align-items:center;gap:16px;flex-wrap:wrap}\nheader h1{font-size:18px;margin:0;letter-spacing:1px}\nheader h1 .sub{color:var(--acc);font-weight:600}\n.badge{font-size:12px;color:var(--sub)}\nmain{flex:1;display:flex;min-height:0}\n#sidebar{width:270px;border-right:1px solid var(--line);background:var(--panel);display:flex;flex-direction:column;min-height:0}\n#content{flex:1;overflow:auto;padding:20px 24px;min-width:0}\n.topbar{display:flex;gap:12px;align-items:center;flex-wrap:wrap}\nselect,input[type=number]{background:var(--panel2);border:1px solid var(--line);color:var(--txt);padding:7px 10px;border-radius:8px;font-size:14px;outline:none}\nselect:focus,input:focus{border-color:var(--acc2)}\ninput[type=number]{width:110px}\nbutton{background:var(--panel2);border:1px solid var(--line);color:var(--txt);padding:8px 14px;border-radius:8px;cursor:pointer;font-size:14px;transition:.15s}\nbutton:hover{border-color:var(--acc2);background:#242e40}\nbutton.primary{background:var(--acc);border-color:var(--acc);color:#1a1405;font-weight:700}\nbutton.primary:hover{filter:brightness(1.1)}\nbutton.danger{border-color:var(--warn);color:var(--warn)}\nbutton.small{padding:4px 9px;font-size:12px}\nbutton:disabled{opacity:.45;cursor:not-allowed}\n.savemeta{font-size:12px;color:var(--sub);margin-top:6px}\n#charlist{overflow:auto;flex:1;padding:8px}\n.charitem{padding:10px 12px;border-radius:10px;cursor:pointer;margin-bottom:6px;border:1px solid transparent;display:flex;justify-content:space-between;align-items:center;gap:8px}\n.charitem:hover{background:var(--panel2)}\n.charitem.sel{background:#24304a;border-color:var(--acc2)}\n.charitem .nm{font-weight:600;font-size:14px}\n.charitem .meta{font-size:11px;color:var(--sub);margin-top:2px}\n.charitem .lv{font-size:12px;color:var(--acc);white-space:nowrap}\n.dot{display:inline-block;width:7px;height:7px;border-radius:50%;margin-right:5px}\n.dot.on{background:var(--ok)}.dot.off{background:#5a6577}\n.section{background:var(--panel);border:1px solid var(--line);border-radius:14px;padding:18px 20px;margin-bottom:18px}\n.section h2{margin:0 0 4px;font-size:16px}\n.section .desc{color:var(--sub);font-size:12px;margin-bottom:14px}\n.charhead{display:flex;align-items:center;gap:14px;flex-wrap:wrap}\n.charhead .big{font-size:24px;font-weight:700}\n.charhead .tag{font-size:12px;padding:3px 9px;border-radius:20px;background:var(--panel2);color:var(--sub);border:1px solid var(--line)}\n.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:12px}\n.field{background:var(--panel2);border:1px solid var(--line);border-radius:10px;padding:10px 12px}\n.field label{display:block;font-size:12px;color:var(--sub);margin-bottom:6px}\n.field label .off{color:#5a6577;font-size:10px;margin-left:4px}\n.field input{width:100%}\n.field.changed{border-color:var(--acc)}\n.field.changed label{color:var(--acc)}\nh3.grp{font-size:13px;color:var(--acc);margin:18px 0 10px;letter-spacing:1px}\ndetails{margin-top:16px}\nsummary{cursor:pointer;color:var(--sub);font-size:13px;user-select:none}\n.moneyrow{display:flex;align-items:center;gap:10px;flex-wrap:wrap}\n.moneyrow .val{font-size:20px;font-weight:700;color:var(--acc)}\n#toast{position:fixed;bottom:24px;left:50%;transform:translateX(-50%);background:#242e40;border:1px solid var(--line);padding:12px 20px;border-radius:10px;font-size:14px;opacity:0;pointer-events:none;transition:.3s;max-width:80%;z-index:50}\n#toast.show{opacity:1}\n#toast.ok{border-color:var(--ok)}#toast.err{border-color:var(--warn)}\n.unsaved{color:var(--acc);font-size:12px;font-weight:600}\n.toolbar{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-top:14px}\n.hint{font-size:12px;color:var(--sub);line-height:1.6}\n.empty{color:var(--sub);padding:40px;text-align:center}\n.quick{display:flex;gap:8px;flex-wrap:wrap;margin-top:10px}\n::-webkit-scrollbar{width:10px;height:10px}::-webkit-scrollbar-thumb{background:#2b3547;border-radius:5px}\n</style>\n</head>\n<body>\n<header>\n  <h1>传颂之物 <span class=\"sub\">虚伪的假面</span> · 人物修改器</h1>\n  <span class=\"badge\">单机离线 · 存档编辑 · 自动备份</span>\n  <div style=\"flex:1\"></div>\n  <span id=\"unsaved\" class=\"unsaved\"></span>\n</header>\n<main>\n  <div id=\"sidebar\">\n    <div style=\"padding:12px\">\n      <div class=\"topbar\">\n        <select id=\"savesel\" style=\"flex:1\"></select>\n        <button class=\"small\" id=\"refreshBtn\" title=\"刷新\">⟳</button>\n      </div>\n      <div class=\"savemeta\" id=\"savemeta\"></div>\n    </div>\n    <div id=\"charlist\"></div>\n  </div>\n  <div id=\"content\">\n    <div class=\"section\">\n      <h2>金钱</h2>\n      <div class=\"desc\">当前存档所持金钱。修改后点击下方「保存修改」写入。</div>\n      <div class=\"moneyrow\">\n        <span class=\"val\" id=\"moneyval\">-</span>\n        <input type=\"number\" id=\"moneyinput\" min=\"0\" max=\"2147483647\">\n        <button class=\"small\" data-money=\"10000\">+1万</button>\n        <button class=\"small\" data-money=\"100000\">+10万</button>\n        <button class=\"small\" data-money=\"9999999\">设为 999万</button>\n      </div>\n    </div>\n    <div id=\"charpage\"></div>\n    <div class=\"section\">\n      <div class=\"toolbar\">\n        <button class=\"primary\" id=\"saveBtn\">💾 保存修改（自动备份）</button>\n        <button id=\"discardBtn\">放弃修改</button>\n        <button id=\"restoreBtn\">↩ 还原备份…</button>\n        <span class=\"hint\" id=\"savehint\"></span>\n      </div>\n      <div class=\"hint\" style=\"margin-top:12px\">\n        流程：选择存档 → 修改人物属性 / 金钱 → 「保存修改」→ 进入游戏<strong>读取该存档</strong>即生效。<br>\n        每次保存前自动备份原存档；「还原备份」可一键回滚。战斗类数值读档后生效。建议先备份再大胆改。\n      </div>\n    </div>\n  </div>\n</main>\n<div id=\"toast\"></div>\n<script>\nlet FIELDS=[],state={slot:null,save:null,sel:0,pending:{money:null,chars:{}}};\nconst $=s=>document.querySelector(s);\nfunction toast(msg,cls){const t=$('#toast');t.textContent=msg;t.className='show '+(cls||'');clearTimeout(t._h);t._h=setTimeout(()=>t.className='',3200);}\nfunction esc(s){return String(s).replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c]));}\nasync function api(url,opt){const r=await fetch(url,opt);const j=await r.json();if(!r.ok)throw new Error(j.error||r.status);return j;}\n\nfunction hasPending(){return state.pending.money!==null||Object.keys(state.pending.chars).length>0;}\nfunction markUnsaved(){$('#unsaved').textContent=hasPending()?'● 有未保存修改':'';$('#saveBtn').disabled=!hasPending();}\nfunction pendVal(idx,key,orig){const c=state.pending.chars[idx];return (c&&c[key]!==undefined)?c[key]:orig;}\nfunction setPend(idx,key,val){if(!state.pending.chars[idx])state.pending.chars[idx]={};state.pending.chars[idx][key]=val;markUnsaved();}\n\nasync function loadSaves(){\n  const {saves,saveDir}=await api('/api/saves');\n  const sel=$('#savesel');sel.innerHTML='';\n  for(const s of saves){\n    const o=document.createElement('option');o.value=s.slot;\n    o.textContent=`存档 ${String(s.slot).padStart(2,'0')} · ${s.desc||''}`;\n    sel.appendChild(o);\n  }\n  if(saves.length){const pick=state.slot&&saves.some(s=>s.slot===state.slot)?state.slot:saves[saves.length-1].slot;sel.value=pick;await loadSave(pick);}\n  $('#savemeta').textContent='目录: '+saveDir;\n}\nasync function loadSave(slot){\n  state.slot=slot;state.pending={money:null,chars:{}};\n  const d=await api('/api/save/'+slot);\n  state.save=d;FIELDS=d.fields;state.sel=0;\n  $('#moneyval').textContent=d.money.toLocaleString();\n  $('#moneyinput').value=d.money;\n  renderCharList();renderCharPage();markUnsaved();\n  $('#savehint').textContent=d.valid?'校验正常':'⚠ 原存档校验异常';\n}\nfunction renderCharList(){\n  const box=$('#charlist');box.innerHTML='';\n  state.save.chars.forEach((c,i)=>{\n    const div=document.createElement('div');\n    div.className='charitem'+(i===state.sel?' sel':'');\n    const lv=pendVal(c.index,'level',c.fields.level);\n    div.innerHTML=`<div><div class=\"nm\"><span class=\"dot ${c.active?'on':'off'}\"></span>${esc(c.name)}</div>\n      <div class=\"meta\">${c.active?'出战':'后备'} · HP ${pendVal(c.index,'hp',c.fields.hp)}</div></div>\n      <div class=\"lv\">Lv ${lv}</div>`;\n    div.onclick=()=>{state.sel=i;renderCharList();renderCharPage();};\n    box.appendChild(div);\n  });\n}\nfunction fieldHTML(c,f){\n  const v=pendVal(c.index,f.key,c.fields[f.key]);\n  const changed=(state.pending.chars[c.index]&&state.pending.chars[c.index][f.key]!==undefined);\n  return `<div class=\"field${changed?' changed':''}\">\n    <label>${esc(f.label)}<span class=\"off\">+${f.off.toString(16).toUpperCase()}</span></label>\n    <input type=\"number\" data-idx=\"${c.index}\" data-key=\"${f.key}\" min=\"${f.min}\" max=\"${f.max}\" value=\"${v}\">\n  </div>`;\n}\nfunction renderCharPage(){\n  const c=state.save.chars[state.sel];const box=$('#charpage');\n  if(!c){box.innerHTML='<div class=\"section empty\">该存档没有人物数据</div>';return;}\n  const core=FIELDS.filter(f=>['level','exp','hp','sp'].includes(f.key));\n  const combat=FIELDS.filter(f=>['atk','def','hit','avoid','mov','jump'].includes(f.key));\n  const adv=FIELDS.filter(f=>f.conf==='adv');\n  box.innerHTML=`<div class=\"section\">\n    <div class=\"charhead\">\n      <span class=\"big\">${esc(c.name)}</span>\n      <span class=\"tag\">${c.active?'出战中':'后备'}</span>\n      <span class=\"tag\">单位ID ${c.unitId}</span>\n      <span class=\"tag\">槽位 ${c.index}</span>\n      <div style=\"flex:1\"></div>\n      <div class=\"quick\">\n        <button class=\"small\" data-quick=\"max\">一键满级满血</button>\n        <button class=\"small\" data-quick=\"hp\">HP/SP 拉满</button>\n        <button class=\"small\" data-quick=\"atk\">攻防 999</button>\n      </div>\n    </div>\n    <h3 class=\"grp\">基础</h3><div class=\"grid\">${core.map(f=>fieldHTML(c,f)).join('')}</div>\n    <h3 class=\"grp\">战斗属性</h3><div class=\"grid\">${combat.map(f=>fieldHTML(c,f)).join('')}</div>\n    <details><summary>进阶字段（未完全标注，按偏移显示，可编辑）</summary>\n      <div class=\"grid\" style=\"margin-top:12px\">${adv.map(f=>fieldHTML(c,f)).join('')}</div>\n    </details>\n  </div>`;\n  box.querySelectorAll('input[data-key]').forEach(inp=>{\n    inp.oninput=()=>{setPend(+inp.dataset.idx,inp.dataset.key,inp.value===''?0:+inp.value);\n      inp.closest('.field').classList.add('changed');renderCharList();};\n  });\n  box.querySelectorAll('[data-quick]').forEach(b=>b.onclick=()=>quick(c,b.dataset.quick));\n}\nfunction quick(c,kind){\n  const set=(k,v)=>setPend(c.index,k,v);\n  if(kind==='max'){set('level',99);set('hp',9999);set('sp',9999);set('atk',999);set('def',999);}\n  if(kind==='hp'){set('hp',9999);set('sp',9999);}\n  if(kind==='atk'){set('atk',999);set('def',999);}\n  renderCharPage();renderCharList();\n}\n$('#moneyinput').oninput=()=>{state.pending.money=$('#moneyinput').value===''?0:+$('#moneyinput').value;markUnsaved();};\ndocument.querySelectorAll('[data-money]').forEach(b=>b.onclick=()=>{\n  const v=+b.dataset.money;const cur=state.pending.money!==null?state.pending.money:state.save.money;\n  const nv=b.textContent.startsWith('设为')?v:Math.min(2147483647,cur+v);\n  state.pending.money=nv;$('#moneyinput').value=nv;markUnsaved();\n});\n$('#saveBtn').onclick=async()=>{\n  try{\n    const body={money:state.pending.money,chars:state.pending.chars};\n    const r=await api('/api/save/'+state.slot,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});\n    toast('已保存并备份（'+r.backup+'）。进游戏读取存档 '+state.slot+' 生效。','ok');\n    await loadSave(state.slot);\n  }catch(e){toast('保存失败: '+e.message,'err');}\n};\n$('#discardBtn').onclick=()=>{state.pending={money:null,chars:{}};$('#moneyinput').value=state.save.money;renderCharList();renderCharPage();markUnsaved();};\n$('#restoreBtn').onclick=async()=>{\n  try{\n    const {backups}=await api('/api/backups/'+state.slot);\n    if(!backups.length){toast('该存档暂无备份','err');return;}\n    const pick=prompt('输入要还原的备份序号（1=最新）：\\n'+backups.slice(0,15).map((f,i)=>(i+1)+'. '+f).join('\\n'),'1');\n    if(!pick)return;const idx=+pick-1;if(!backups[idx])return;\n    if(!confirm('还原将覆盖当前存档 '+state.slot+'（会先再备份一次）。继续？'))return;\n    await api('/api/restore',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({file:backups[idx]})});\n    toast('已还原','ok');await loadSave(state.slot);\n  }catch(e){toast('还原失败: '+e.message,'err');}\n};\n$('#savesel').onchange=()=>{if(hasPending()&&!confirm('有未保存修改，切换存档将丢弃。继续？')){$('#savesel').value=state.slot;return;}loadSave(+$('#savesel').value);};\n$('#refreshBtn').onclick=()=>loadSaves();\nloadSaves().catch(e=>toast('加载失败: '+e.message,'err'));\n</script>\n</body>\n</html>";

function checksum(buf){const n=buf.length-0x10;let sum=n>>>0,hash=1;for(let i=0x10;i<buf.length;i++){sum=(sum+buf[i])>>>0;hash=Math.imul(hash,sum)>>>0;hash=(hash+sum)>>>0;if(hash===0)hash=1;}return{A:sum,B:hash};}
function applyChecksum(buf){const c=checksum(buf);buf.writeUInt32LE(c.A,0);buf.writeUInt32LE(c.B,4);return c;}
function verifyChecksum(buf){const c=checksum(buf);return c.A===buf.readUInt32LE(0)&&c.B===buf.readUInt32LE(4);}
function readField(buf,o,f){return f.type==='u32'?buf.readUInt32LE(o+f.off):buf.readUInt16LE(o+f.off);}
function writeField(buf,o,f,v){if(f.type==='u32')buf.writeUInt32LE(v>>>0,o+f.off);else buf.writeUInt16LE(v&0xffff,o+f.off);}
function slotFile(slot){return path.join(SAVE_DIR,`GAME-${String(slot).padStart(3,'0')}.DAT`);}

function listSaves(){const out=[];if(!fs.existsSync(SAVE_DIR))return out;
  for(const name of fs.readdirSync(SAVE_DIR)){const m=name.match(/^GAME-(\d+)\.DAT$/i);if(!m)continue;
    const full=path.join(SAVE_DIR,name);const st=fs.statSync(full);
    let info={slot:+m[1],file:name,size:st.size,mtime:st.mtime.toISOString()};
    try{const buf=fs.readFileSync(full);info.valid=verifyChecksum(buf);info.money=buf.readUInt32LE(MONEY_OFF);
      let e=0x28;while(e<buf.length&&buf[e]!==0)e++;info.desc=buf.toString('utf8',0x28,e);
      info.chapter=buf.readUInt32LE(0x10c);
      info.year=buf.readUInt16LE(0x5a);info.month=buf.readUInt16LE(0x5c);info.day=buf.readUInt16LE(0x5e);
      info.hour=buf.readUInt16LE(0x60);info.min=buf.readUInt16LE(0x62);
    }catch(e){info.valid=false;}
    out.push(info);}
  out.sort((a,b)=>a.slot-b.slot);return out;}
function readSave(slot){return fs.readFileSync(slotFile(slot));}
function getCharacters(buf){const chars=[];
  for(let i=0;i<CHAR_SLOTS;i++){const off=CHAR_BASE+i*CHAR_STRIDE;if(off+CHAR_STRIDE>buf.length)break;
    const unitId=buf.readUInt32LE(off+0x270);const level=buf.readUInt16LE(off);const hp=buf.readUInt32LE(off+8);
    if(level===0&&unitId===0)continue;
    const name=UNIT_NAMES[unitId]||('单位'+unitId);const fields={};
    for(const f of FIELDS)fields[f.key]=readField(buf,off,f);
    chars.push({index:i,off,unitId,name,active:hp>0,fields});}
  return chars;}
function getMoney(buf){return buf.readUInt32LE(MONEY_OFF);}
function applyChanges(buf,changes){
  if(typeof changes.money==='number')buf.writeUInt32LE(Math.max(0,Math.min(0x7fffffff,changes.money|0)),MONEY_OFF);
  if(changes.chars){for(const k of Object.keys(changes.chars)){const off=CHAR_BASE+(+k)*CHAR_STRIDE;const vals=changes.chars[k];
    for(const f of FIELDS){if(vals[f.key]===undefined)continue;let v=Math.round(+vals[f.key]);if(!isFinite(v))continue;
      v=Math.max(f.min,Math.min(f.max,v));writeField(buf,off,f,v);}}}
  applyChecksum(buf);return buf;}
function backupSave(slot){if(!fs.existsSync(BACKUP_DIR))fs.mkdirSync(BACKUP_DIR,{recursive:true});
  const ts=new Date().toISOString().replace(/[:.]/g,'-');
  const bak=path.join(BACKUP_DIR,`GAME-${String(slot).padStart(3,'0')}_${ts}.DAT`);
  fs.copyFileSync(slotFile(slot),bak);return bak;}
function writeSave(slot,buf){applyChecksum(buf);fs.writeFileSync(slotFile(slot),buf);}

function sendJSON(res,code,obj){const b=Buffer.from(JSON.stringify(obj),'utf8');res.writeHead(code,{'Content-Type':'application/json; charset=utf-8','Content-Length':b.length});res.end(b);}
function readBody(req){return new Promise((resolve,reject)=>{let d='';req.on('data',c=>{d+=c;if(d.length>5e6){reject(new Error('body too large'));req.destroy();}});req.on('end',()=>{try{resolve(d?JSON.parse(d):{});}catch(e){reject(e);}});req.on('error',reject);});}

const server=http.createServer(async(req,res)=>{
  try{
    const u=new URL(req.url,'http://localhost');const p=u.pathname;let m;
    if(p==='/api/saves'&&req.method==='GET')return sendJSON(res,200,{saves:listSaves(),saveDir:SAVE_DIR});
    if((m=p.match(/^\/api\/save\/(\d+)$/))&&req.method==='GET'){const slot=+m[1];const buf=readSave(slot);
      return sendJSON(res,200,{slot,valid:verifyChecksum(buf),money:getMoney(buf),chars:getCharacters(buf),fields:FIELDS});}
    if((m=p.match(/^\/api\/save\/(\d+)$/))&&req.method==='POST'){const slot=+m[1];const changes=await readBody(req);
      const bak=backupSave(slot);const buf=readSave(slot);applyChanges(buf,changes);writeSave(slot,buf);
      return sendJSON(res,200,{ok:true,backup:path.basename(bak),valid:verifyChecksum(buf),money:getMoney(buf),chars:getCharacters(buf)});}
    if((m=p.match(/^\/api\/backups\/(\d+)$/))&&req.method==='GET'){const slot=+m[1];let list=[];
      if(fs.existsSync(BACKUP_DIR))list=fs.readdirSync(BACKUP_DIR).filter(f=>f.startsWith(`GAME-${String(slot).padStart(3,'0')}_`)).sort().reverse();
      return sendJSON(res,200,{backups:list});}
    if(p==='/api/restore'&&req.method==='POST'){const{file}=await readBody(req);
      const full=path.join(BACKUP_DIR,path.basename(file));
      if(!fs.existsSync(full))return sendJSON(res,404,{error:'backup not found'});
      const mm=path.basename(file).match(/^GAME-(\d+)_/);if(!mm)return sendJSON(res,400,{error:'bad backup name'});
      const slot=+mm[1];backupSave(slot);writeSave(slot,fs.readFileSync(full));
      return sendJSON(res,200,{ok:true,slot});}
    if(p==='/'||p==='/index.html'){const b=Buffer.from(HTML,'utf8');res.writeHead(200,{'Content-Type':'text/html; charset=utf-8','Content-Length':b.length});return res.end(b);}
    sendJSON(res,404,{error:'not found'});
  }catch(e){sendJSON(res,500,{error:String(e.message||e)});}
});
server.on('error',e=>{console.error('启动失败: '+e.message);console.error('可能端口 '+PORT+' 已被占用（修改器已在运行？）。');process.exit(1);});
server.listen(PORT,'127.0.0.1',()=>{
  console.log('传颂之物 虚伪的假面 修改器已启动: http://127.0.0.1:'+PORT);
  console.log('存档目录: '+SAVE_DIR);
  console.log('备份目录: '+BACKUP_DIR);
  if(!process.argv.includes('--no-open')){
    try{require('child_process').exec('cmd /c start "" "http://127.0.0.1:'+PORT+'"');}catch(e){}
  }
});